layers.vertex:
attribute vec3 aO, aE; attribute float aT; uniform float uTime; varying float vS, vY, vU, vL;
    void main(){
      float u = uTime - aT - 0.06; if (u < 0. || u > 0.72){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec3 d = aE - aO; float L = length(d); vec3 f = d/L;
      float s = position.x*.5 + .5, W = .85;                             // body-tall smear (a Fighter is taller than wide)
      vec3 P = aO + f*(s*L - .05) + vec3(0., 1.0, 0.);                // ends inside the body, not behind it
      vec3 cside = normalize(cross(f, P - cameraPosition));
      vec3 side = normalize(vec3(0., 1., 0.) + .3*cside*sign(dot(cside, vec3(0., 1., 0.)) + 1e-4));   // stays upright: tall from the side, narrow from above
      vS = s; vY = position.y*W; vU = u; vL = L;
      gl_Position = projectionMatrix*viewMatrix*vec4(P + side*position.y*W, 1.);
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying float vS, vY, vU, vL; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    void main(){
      float h = 1. - pow(1. - clamp(vU/0.22, 0., 1.), 3.);   // head = Fighter position (same ease as the rush)
      float q = vS/max(h, .001);                                           // 0 at origin, 1 at the Fighter
      float prof = pow(sin(1.5708*clamp(q, 0., 1.)), 1.1);                // thin at origin, full body height near the Fighter
      float blend = smoothstep(1.02, .7, q);                               // melts softly into the body — no hard front edge
      float arr = pow(prof, 3.);                                                        // arrival end: the part that stays longest
      float wipe = max(vU - 0.32, 0.)/.32;
      float alive = smoothstep(wipe - .08 - .35*arr, wipe + .2 - .35*arr, q);
      float fade = 1. - smoothstep(0.54, 0.72, vU);
      float band = 0.;
      // Fios independentes: o vazio entre eles mantém a silhueta do corpo legível.
      for (int i=0;i<4;i++){
        float fi = float(i), centre = (fi - 1.5)*.18*prof + sin(vS*8. - vU*6. + fi*2.1)*.035*prof;
        float width = (.025 + .06*prof)*(.8 + .2*sin(vS*5. + fi*1.7));
        float breakup = .35 + .65*smoothstep(.15, .75, .5 + .5*sin(vS*15. - vU*8. + fi)*sin(vS*7. + fi*2.3));
        band += exp(-pow(abs(vY - centre)/width, 1.6))*breakup;
      }
      float core = band*.12;
      float k = alive*fade*pow(prof, .75)*blend;
      vec3 col = mix(mix(uOrange, uGold, .3 + .7*prof), vec3(.46, .45, .48), .25);   // a little desaturated
      vec3 outc = (col*band*(.10 + .09*prof) + mix(uGold, vec3(1., .96, .88), .5)*core*.065*prof)*k;
      outc *= 1. - smoothstep(.72, .83, abs(vY));
      gl_FragColor = vec4(outc, 1.);
    }
